package com.pradeep.tapcounter;
import android.app.Activity;import android.os.Bundle;import android.webkit.*;import android.graphics.Color;
public class MainActivity extends Activity { private WebView webView; @Override public void onCreate(Bundle b){super.onCreate(b);getWindow().setStatusBarColor(Color.rgb(11,16,32));getWindow().setNavigationBarColor(Color.rgb(11,16,32));webView=new WebView(this);WebSettings s=webView.getSettings();s.setJavaScriptEnabled(true);s.setDomStorageEnabled(true);s.setDatabaseEnabled(true);s.setAllowFileAccess(true);s.setAllowContentAccess(true);s.setMediaPlaybackRequiresUserGesture(false);webView.setWebViewClient(new WebViewClient());webView.setWebChromeClient(new WebChromeClient());webView.setBackgroundColor(Color.rgb(11,16,32));setContentView(webView);webView.loadUrl("file:///android_asset/index.html");} @Override public void onBackPressed(){if(webView!=null&&webView.canGoBack())webView.goBack();else super.onBackPressed();}}
